async function response<T>(r:Response):Promise<T>{
 const body:unknown=await r.json();
 if(!r.ok){
  const problem=body&&typeof body==='object'?body:null;
  const message=problem&&'error' in problem&&typeof problem.error==='string'?problem.error:'操作失敗，請稍後重試。';
  const code=problem&&'code' in problem&&['DATABASE_URL_MISSING','D1_BINDING_MISSING','DATABASE_UNAVAILABLE'].includes(String(problem.code))?problem.code as DatabaseIssue:undefined;
  const target=problem&&'deployTarget' in problem&&(problem.deployTarget==='zeabur'||problem.deployTarget==='cloudflare')?problem.deployTarget:undefined;
  throw new ApiError(message,code,target);
 }
 return body as T;
}
